<?php
require_once __DIR__ . '/../includes/auth.php'; require_login('employee'); $user = current_user();
$statement = db()->prepare('SELECT la.*, lt.name AS leave_type FROM leave_applications la JOIN leave_types lt ON lt.id = la.leave_type_id WHERE la.user_id = ? ORDER BY la.start_date DESC'); $statement->execute([$user['id']]);
$pageTitle = 'Leave history'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="detail-heading"><div><span class="eyebrow">Time away / Record</span><h2>Your leave history</h2><p class="muted mb-0">Every request, review, and decision in one place.</p></div><a class="btn btn-primary" href="<?= e(base_url('employee/apply-leave.php')) ?>">New request <span>&rarr;</span></a></div><section class="panel"><table class="table"><thead><tr><th>Request</th><th>Dates</th><th>Days</th><th>Reason</th><th>Status</th><th>Admin remarks</th></tr></thead><tbody><?php while ($item = $statement->fetch()): ?><tr><td><strong><?= e($item['leave_type']) ?></strong><br><small class="muted">#LR-<?= str_pad((string) $item['id'], 4, '0', STR_PAD_LEFT) ?></small></td><td><?= e(date('M j', strtotime($item['start_date']))) ?> - <?= e(date('M j, Y', strtotime($item['end_date']))) ?></td><td><?= e((string) $item['days']) ?></td><td><?= e($item['reason']) ?></td><td><span class="status status-<?= e($item['status']) ?>"><?= e($item['status']) ?></span></td><td><?= e($item['admin_remarks'] ?: 'Awaiting review') ?></td></tr><?php endwhile; ?></tbody></table></section></div><?php require __DIR__ . '/../includes/footer.php'; ?>
